/* Всё «оформление» графика берётся из токенов текущей темы Gravity UI,
   поэтому оси, сетка, текст и подсказка автоматически следуют light/dark. */
.line-chart {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.line-chart__legend {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 16px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.line-chart__legend-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.line-chart__key {
  flex: none;
  width: 14px;
  height: 2px;
  border-radius: 1px;
}

.line-chart__canvas {
  position: relative;
  width: 100%;
}

.line-chart__canvas svg {
  display: block;
  overflow: visible;
  touch-action: pan-y;
}

.line-chart__canvas svg:focus-visible {
  outline: 2px solid var(--g-color-line-focus);
  outline-offset: 4px;
  border-radius: var(--g-border-radius-s);
}

.line-chart__grid {
  stroke: var(--g-color-line-generic);
  stroke-width: 1;
  shape-rendering: crispEdges;
}

.line-chart__baseline {
  stroke: var(--g-color-line-generic-accent);
  stroke-width: 1;
  shape-rendering: crispEdges;
}

.line-chart__crosshair {
  stroke: var(--g-color-line-generic-active);
  stroke-width: 1;
  shape-rendering: crispEdges;
}

.line-chart__tick {
  fill: var(--g-color-text-secondary);
  font-family: var(--g-text-body-font-family);
  font-size: var(--g-text-caption-2-font-size);
  font-variant-numeric: tabular-nums;
}

.line-chart__line {
  fill: none;
  stroke-width: 2;
  stroke-linejoin: round;
  stroke-linecap: round;
}

.line-chart__dot {
  stroke: var(--g-color-base-background);
  stroke-width: 2;
  paint-order: stroke;
}

.line-chart__end-value {
  fill: var(--g-color-text-primary);
  font-family: var(--g-text-body-font-family);
  font-size: var(--g-text-body-1-font-size);
  font-weight: var(--g-text-accent-font-weight);
}

.line-chart__end-name {
  fill: var(--g-color-text-secondary);
  font-family: var(--g-text-body-font-family);
  font-size: var(--g-text-body-1-font-size);
}

.line-chart__tooltip {
  position: absolute;
  z-index: 1;
  min-width: 160px;
  padding: 8px 12px;
  pointer-events: none;
  background: var(--g-color-base-float);
  border: 1px solid var(--g-color-line-generic);
  border-radius: var(--g-border-radius-m);
  box-shadow: 0 4px 16px var(--g-color-sfx-shadow);
}

.line-chart__tooltip-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
  white-space: nowrap;
}

